	@Test
	void closingWhileConsumerChecksPublishedResultDoesNotDereferenceClearedIteration() throws Exception {
		FederationContext context = mock(FederationContext.class);
		FederationManager manager = mock(FederationManager.class);
		@SuppressWarnings("unchecked")
		ControlledWorkerScheduler<BindingSet> scheduler = mock(ControlledWorkerScheduler.class);
		when(context.getManager()).thenReturn(manager);
		when(manager.getUnionScheduler()).thenReturn(scheduler);
		ParallelServiceExecutor executor = new ParallelServiceExecutor(mock(FedXService.class),
				mock(FederationEvaluationStrategy.class), EmptyBindingSet.getInstance(), context);
		CountDownLatch checking = new CountDownLatch(1);
		CountDownLatch released = new CountDownLatch(1);
		AbstractCloseableIteration<BindingSet> result = new AbstractCloseableIteration<>() {
			@Override
			public boolean hasNext() {
				checking.countDown();
				try {
					released.await();
				} catch (InterruptedException interrupted) {
					Thread.currentThread().interrupt();
				}
				return true;
			}

			@Override
			public BindingSet next() {
				return EmptyBindingSet.getInstance();
			}

			@Override
			protected void handleClose() {
				released.countDown();
			}
		};
		executor.run();
		executor.addResult(result);
		AtomicReference<Throwable> failure = new AtomicReference<>();
		AtomicReference<Boolean> observed = new AtomicReference<>();
		Thread consumer = Thread.ofVirtual().start(() -> {
			try {
				observed.set(executor.hasNext());
			} catch (Throwable thrown) {
				failure.set(thrown);
			}
		});
		try {
			assertThat(checking.await(5, TimeUnit.SECONDS)).isTrue();
			executor.close();
		} finally {
			released.countDown();
			consumer.join();
		}
		assertThat(failure.get()).isNull();
		assertThat(observed.get()).isFalse();
	}

	@Test
	void closingDuringRemoteDrainClosesTheActiveSource() throws Exception {
		FederationContext context = mock(FederationContext.class);
		FederationManager manager = mock(FederationManager.class);
		@SuppressWarnings("unchecked")
		ControlledWorkerScheduler<BindingSet> scheduler = mock(ControlledWorkerScheduler.class);
		when(context.getManager()).thenReturn(manager);
		when(manager.getUnionScheduler()).thenReturn(scheduler);
		FedXService service = mock(FedXService.class);
		Service wrapped = mock(Service.class);
		when(service.getService()).thenReturn(wrapped);
		FederationEvaluationStrategy strategy = mock(FederationEvaluationStrategy.class);
		QueryEvaluationStep step = mock(QueryEvaluationStep.class);
		when(strategy.precompile(wrapped)).thenReturn(step);
		CountDownLatch started = new CountDownLatch(1);
		CountDownLatch released = new CountDownLatch(1);
		AtomicInteger closeCount = new AtomicInteger();
		AbstractCloseableIteration<BindingSet> source = new AbstractCloseableIteration<>() {
			@Override
			public boolean hasNext() {
				started.countDown();
				try {
					released.await();
				} catch (InterruptedException interrupted) {
					Thread.currentThread().interrupt();
				}
				return false;
			}

			@Override
			public BindingSet next() {
				throw new AssertionError("No row was supplied");
			}

			@Override
			protected void handleClose() {
				closeCount.incrementAndGet();
				released.countDown();
			}
		};
		when(step.evaluate(any(BindingSet.class))).thenReturn(source);
		AtomicReference<ParallelTask<BindingSet>> scheduled = new AtomicReference<>();
		doAnswer(invocation -> {
			scheduled.set(invocation.getArgument(0));
			return null;
		}).when(scheduler).schedule(any());
		ParallelServiceExecutor executor = new ParallelServiceExecutor(service, strategy,
				EmptyBindingSet.getInstance(), context);
		executor.run();
		AtomicReference<Throwable> workerFailure = new AtomicReference<>();
		Thread worker = Thread.ofVirtual().start(() -> {
			try (var ignored = scheduled.get().performTask()) {
			} catch (Throwable failure) {
				workerFailure.set(failure);
			}
		});
		try {
			assertThat(started.await(5, TimeUnit.SECONDS)).isTrue();
			executor.close();
			assertThat(closeCount).hasValue(1);
		} finally {
			released.countDown();
			worker.join();
		}
		assertThat(workerFailure.get()).isNull();
	}

